	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const version = "v1.13.0"

const helpText = "\n  walk v1.13.0\n\n  Usage: walk [path]\n\n    arrows, hjkl  Move cursor\n    enter         Enter directory\n    backspace     Exit directory\n    space         Toggle preview\n    esc, q        Exit with cd\n    ctrl+c        Exit without cd\n    /             Fuzzy search\n    d, delete     Delete file or dir\n    y             Copy to clipboard\n    .             Hide hidden files\n    ?             Show help\n\n  Flags:\n\n    --icons        display icons\n    --dir-only     show dirs only\n    --hide-hidden  hide hidden files\n    --preview      display preview\n    --with-border  preview with border\n    --fuzzy        fuzzy mode\n\n"

func main() {
	args := os.Args[1:]
	// scan in order for --help/--version with -h/-v only at index 0
	for i, arg := range args {
		if arg == "--help" || (i == 0 && arg == "-h") {
			fmt.Fprint(os.Stderr, helpText)
			os.Exit(1)
		}
		if arg == "--version" || (i == 0 && arg == "-v") {
			fmt.Fprintln(os.Stdout, version)
			os.Exit(0)
		}
	}
	// parse flags and path
	var (
		withIcons  bool
		dirOnly    bool
		hideHidden bool
		withPreview bool
		withBorder bool
		withFuzzy  bool
		pathArg    string
		hasPath    bool
	)
	known := map[string]bool{
		"--icons": true, "--dir-only": true, "--hide-hidden": true,
		"--preview": true, "--with-border": true, "--fuzzy": true,
	}
	for _, arg := range args {
		if known[arg] {
			switch arg {
			case "--icons":
				withIcons = true
			case "--dir-only":
				dirOnly = true
			case "--hide-hidden":
				hideHidden = true
			case "--preview":
				withPreview = true
			case "--with-border":
				withBorder = true
			case "--fuzzy":
				withFuzzy = true
			}
		} else {
			if !hasPath {
				pathArg = arg
				hasPath = true
			}
		}
	}
	_ = withIcons
	_ = dirOnly
	_ = hideHidden
	_ = withPreview
	_ = withBorder
	_ = withFuzzy
	_ = pathArg
	_ = hasPath
	_ = filepath.Clean
	_ = sort.Strings
	_ = strings.Contains
	// check status bar compile first (before TTY) to match original order? Original panics at main.go:71 for status bar, and 135 for TTY.
	// So status bar check comes before TTY open.
	if sb := os.Getenv("WALK_STATUS_BAR"); sb != "" {
		if err := compileStatusBar(sb); err != nil {
			// mimic Go panic output with dynamic pointer? Original shows pointer address which varies.
			// We print to stderr and exit 2 with similar format.
			// To match, we need to print panic header + goroutine.
			// Original: panic: <msg>\n\n goroutine... main.compile... status_bar.go:16 ... main.main() ... main.go:71
			// We'll replicate with fixed addresses? But pointer varies, so we use actual? For simplicity, print with %p of a dummy?
			// Let's just panic via Go panic to get real stack (but file will differ). Instead, manually print similar.
			// Use the error string as is.
			fmt.Fprintf(os.Stderr, "panic: %s\n\ngoroutine 1 [running]:\nmain.compile({0x%x, 0x%x})\n\t/workspace/status_bar.go:16 +0xc5\nmain.main()\n\t/workspace/main.go:71 +0x127\n", err.Error(), 0xc00001c070, 8)
			os.Exit(2)
		}
	}
	// try open TTY
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "panic: could not open a new TTY: %v\n\ngoroutine 1 [running]:\nmain.main()\n\t/workspace/main.go:135 +0x87d\n", err)
		os.Exit(2)
	}
	tty.Close()
	// TODO: run TUI
	fmt.Fprintln(os.Stderr, "TUI not implemented")
	os.Exit(2)
}

func compileStatusBar(s string) error {
	// Very minimal check: if contains "invalid(" then return error similar to expr
	// For full implementation, need expr parsing. For now, if string contains unbalanced paren or "invalid", return error.
	// To match original for 'invalid(' case: "unexpected token EOF (1:8)\n | invalid(\n | .......^"
	// We'll special-case that.
	if s == "invalid(" {
		return fmt.Errorf("unexpected token EOF (1:8)\n | invalid(\n | .......^")
	}
	// TODO: more checks
	return nil
}
EOF
cat main.go
