			return fmt.Sprintf("48;5;%dm", n)
		} else if len(hex) == 3 {
			var rs, gs, bs string
			rs = string([]byte{hex[0], hex[0]})
			gs = string([]byte{hex[1], hex[1]})
			bs = string([]byte{hex[2], hex[2]})
