func palette256ToRGB(n int) (int, int, int) {
	// standard 256 palette
	if n < 16 {
		// basic
		cols := [16][3]int{{0,0,0},{128,0,0},{0,128,0},{128,128,0},{0,0,128},{128,0,128},{0,128,128},{192,192,192},{128,128,128},{255,0,0},{0,255,0},{255,255,0},{0,0,255},{255,0,255},{0,255,255},{255,255,255}}
		if n>=0 && n<16 { return cols[n][0], cols[n][1], cols[n][2] }
	}
	if n >= 16 && n <= 231 {
		n -= 16
		r := n / 36
		g := (n % 36) / 6
		b := n % 6
		conv := func(v int) int {
			if v==0 { return 0 }
			return 55 + v*40
		}
		return conv(r), conv(g), conv(b)
	}
	if n >= 232 {
		v := 8 + (n-232)*10
		return v,v,v
	}
	return 130,93,242
}
func rgbTo256(r,g,b int) int {
	// approximate: if red dominant and ff0000 -> 196
	if r==255 && g==0 && b==0 { return 196 }
	if r==255 && g==255 && b==255 { return 231 }
	// generic: map to 216 cube
	ri := (r*5+127)/255
	gi := (g*5+127)/255
	bi := (b*5+127)/255
	if ri<0 {ri=0}; if ri>5 {ri=5}
	if gi<0 {gi=0}; if gi>5 {gi=5}
	if bi<0 {bi=0}; if bi>5 {bi=5}
	return 16 + ri*36 + gi*6 + bi
}

