// ===== file entry =====
type FileEntry struct {
	Name string
	IsDir bool
	Mode os.FileMode
	Info os.FileInfo
	FullPath string
}

func listFiles(dir string, hideHidden bool, dirOnly bool) ([]FileEntry, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var out []FileEntry
	for _, e := range entries {
		name := e.Name()
		if hideHidden && strings.HasPrefix(name, ".") {
			continue
		}
		info, err := e.Info()
		var mode os.FileMode
		var isDir bool
		if err == nil {
			mode = info.Mode()
			isDir = info.IsDir()
		} else {
			isDir = e.IsDir()
		}
		if dirOnly && !isDir {
			continue
		}
		full := filepath.Join(dir, name)
		out = append(out, FileEntry{Name: name, IsDir: isDir, Mode: mode, Info: info, FullPath: full})
	}
	// os.ReadDir already sorted, but ensure
	sort.Slice(out, func(i,j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}
