	// Simplify: return current user/group? Original for /tmp/walktest files owned by agent returns "agent agent".
	// We'll try to get uid/gid via syscall, else fallback to current.
	if info == nil {
		if u, err := user.Current(); err==nil { return u.Username+" "+u.Username }
		return "agent agent"
	}
	// try stat
	if st, ok := info.Sys().(*syscall.Stat_t); ok {
		uid := st.Uid
		gid := st.Gid
		uName := strconv.Itoa(int(uid))
		gName := strconv.Itoa(int(gid))
		if u, err := user.LookupId(strconv.Itoa(int(uid))); err==nil { uName = u.Username }
		if g, err := user.LookupGroupId(strconv.Itoa(int(gid))); err==nil { gName = g.Name }
		return uName+" "+gName
	}
	if u, err := user.Current(); err==nil { return u.Username+" "+u.Username }
	return "agent agent"
}
func modTimeString(info os.FileInfo) string {
	if info == nil { return "" }
	t := info.ModTime()
	// format like "Sep  4 02:55" -> Jan _2 15:04
	return t.Format("Jan _2 15:04")
}

