func humanSize(sz int64) string {
	if sz < 1024 {
		return fmt.Sprintf("%dB", sz)
	} else if sz < 1024*1024 {
		if sz%1024 == 0 {
			return fmt.Sprintf("%dK", sz/1024)
		}
		return fmt.Sprintf("%.1fK", float64(sz)/1024)
	} else if sz < 1024*1024*1024 {
		if sz%(1024*1024)==0 {
			return fmt.Sprintf("%dM", sz/(1024*1024))
		}
		return fmt.Sprintf("%.1fM", float64(sz)/(1024*1024))
	}
	if sz%(1024*1024*1024)==0 {
		return fmt.Sprintf("%dG", sz/(1024*1024*1024))
	}
	return fmt.Sprintf("%.1fG", float64(sz)/(1024*1024*1024))
}
func modeString(info os.FileInfo, isDir bool) string {
	if info == nil {
		if isDir { return "drwxr-xr-x" }
		return "-rw-r--r--"
	}
	m := info.Mode()
	var sb strings.Builder
	if m.IsDir() {
		sb.WriteByte('d')
	} else if m&os.ModeSymlink != 0 {
		sb.WriteByte('l')
	} else {
		sb.WriteByte('-')
	}
	perm := m.Perm()
	for i:=8; i>=0; i-- {
		bit := (perm>>uint(i))&1
		pos := (8-i)%3
		var c byte
		if pos==0 {
			if bit==1 {c='r'} else {c='-'}
		} else if pos==1 {
			if bit==1 {c='w'} else {c='-'}
		} else {
			if bit==1 {c='x'} else {c='-'}
		}
		sb.WriteByte(c)
	}
	return sb.String()
}
