		return "agent agent"
	}
	// try stat
	if st, ok := info.Sys().(*syscall.Stat_t); ok {
		uid := st.Uid
		gid := st.Gid
		uName := strconv.Itoa(int(uid))
		gName := strconv.Itoa(int(gid))
		if u, err := user.LookupId(strconv.Itoa(int(uid))); err==nil { uName = u.Username }
		if g, err := user.LookupGroupId(strconv.Itoa(int(gid))); err==nil { gName = g.Name }
		return uName+" "+gName
	}
	if u, err := user.Current(); err==nil { return u.Username+" "+u.Username }
	return "agent agent"
}
